// Import of required libraries
import { test, expect, SkyrampClient, getValue } from '@skyramp/skyramp';
import { getOwnersList } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const ownersGetResponse = await getOwnersList(client);

    expect(ownersGetResponse.statusCode, 'status code').toBe(200);
    expect(getValue(ownersGetResponse, "0.id"), 'first owner id').not.toBeNull();
    expect(getValue(ownersGetResponse, "9.id"), 'tenth owner id').not.toBeNull();
    expect(getValue(ownersGetResponse, "10"), 'eleventh owner').toBeNull();

    const ownersGet1Response = await getOwnersList(client, {"sort": ["city"]});

    expect(ownersGet1Response.statusCode, 'status code').toBe(200);
    expect(getValue(ownersGet1Response, "9.id"), 'tenth owner id').not.toBeNull();
    expect(getValue(ownersGet1Response, "10"), 'eleventh owner').toBeNull();
    expect(getValue(ownersGet1Response, "0.city"), 'first city ascending').toBe("Madison");
    expect(getValue(ownersGet1Response, "1.city"), 'second city ascending').toBe("Madison");
    expect(getValue(ownersGet1Response, "9.city"), 'last city ascending').toBe("Windsor");
});
